1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.section.clazz.Flow;
4	import net.officefloor.server.http.ServerHttpConnection;
5	import org.springframework.samples.petclinic.rest.support.IdempotencyStore;
6	
7	/**
8	 * First step of the create pipeline. When the request carries an {@code Idempotency-Key}
9	 * header already seen for a successful create, routes to {@link RespondWithExistingOwner}
10	 * with the originally created owner id — a 200 replay rather than a duplicate create.
11	 * Otherwise (no key, or a key not yet seen) routes to the normal create pipeline; a new
12	 * key is remembered after the owner is saved by {@link RecordIdempotencyKey}.
13	 *
14	 * <p>Reads only the header, never the body, so {@link ValidateOwnerRequiredFields} remains
15	 * the sole step that binds {@code @RequestBody}.
16	 */
17	public class CheckIdempotencyKey {
18	
19	    @FunctionalInterface
20	    public interface ExistingOwnerFlow {
21	        void flow(Integer ownerId);
22	    }
23	
24	    @FunctionalInterface
25	    public interface ProceedFlow {
26	        void flow();
27	    }
28	
29	    public void service(ServerHttpConnection connection, IdempotencyStore store,
30	            @Flow("existing") ExistingOwnerFlow existing, @Flow("proceed") ProceedFlow proceed) {
31	        String key = IdempotencyKeys.read(connection);
32	        if (key != null) {
33	            Integer ownerId = store.find(key);
34	            if (ownerId != null) {
35	                existing.flow(ownerId); // replay the original create with 200
36	                return;
37	            }
38	        }
39	        proceed.flow(); // fresh create — run the normal pipeline
40	    }
41	}
