1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.regex.Pattern;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
8	
9	/**
10	 * Normalizes an optional owner email. When absent (null or blank) the request is left untouched, so
11	 * email stays optional. When present it must be a syntactically valid address; the validated value is
12	 * lower-cased and stored back on the {@link OwnerFieldsDto} in place so {@link BuildOwner} and
13	 * {@link ApplyOwner} persist and return the lower-cased form. An invalid address is rejected with 400
14	 * via {@link InvalidEmailException}.
15	 */
16	public class NormalizeOwnerEmail {
17	
18	    /**
19	     * A single {@code @}, with at least one non-space/non-{@code @} character on the local side and a
20	     * dotted domain on the other — enough to reject syntactically malformed addresses.
21	     */
22	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
23	
24	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
25	        String email = request.getEmail();
26	        if (email == null || email.isBlank()) {
27	            return;
28	        }
29	        String trimmed = email.trim();
30	        if (!EMAIL.matcher(trimmed).matches()) {
31	            throw new InvalidEmailException(email);
32	        }
33	        request.setEmail(trimmed.toLowerCase());
34	    }
35	}
