1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Set;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;
8	
9	/**
10	 * Rejects an owner email whose domain is on the disposable-domain blocklist. Runs after
11	 * {@link NormalizeOwnerEmail}, so the email is already trimmed, lower-cased and syntactically valid.
12	 * Email is optional: when absent (null or blank) this step does nothing. A blocked domain is rejected
13	 * with 400 via {@link DisposableEmailDomainException}.
14	 */
15	public class ValidateOwnerEmailDomain {
16	
17	    private static final Set<String> BLOCKED_DOMAINS =
18	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
19	
20	    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
21	        String email = request.getEmail();
22	        if (email == null || email.isBlank()) {
23	            return;
24	        }
25	        int at = email.lastIndexOf('@');
26	        if (at < 0) {
27	            return;
28	        }
29	        String domain = email.substring(at + 1).trim().toLowerCase();
30	        if (BLOCKED_DOMAINS.contains(domain)) {
31	            throw new DisposableEmailDomainException(domain);
32	        }
33	    }
34	}
