1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
6	
7	/**
8	 * Validates the postcode on create WHEN PRESENT. A supplied postcode must be exactly four digits
9	 * and, for a city with a known region, fall within that region's range (see {@link PostcodeRegions});
10	 * otherwise the request is rejected 400 via {@link InvalidPostcodeException}. Postcode is optional:
11	 * when absent (null or blank) this step does nothing, keeping the create contract backward-compatible.
12	 * Reads the already-bound {@link OwnerFieldsDto}; the value is left untouched for {@link BuildOwner}
13	 * to map so it is stored and returned as given.
14	 */
15	public class ValidateOwnerPostcode {
16	
17	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
18	        String postcode = request.getPostcode();
19	        if (postcode == null || postcode.isBlank()) {
20	            return;
21	        }
22	        if (!postcode.matches("^[0-9]{4}$")) {
23	            throw new InvalidPostcodeException("Postcode must be four digits: " + postcode);
24	        }
25	        if (!PostcodeRegions.isValidFor(request.getCity(), postcode)) {
26	            throw new InvalidPostcodeException(
27	                    "Postcode " + postcode + " is not valid for city " + request.getCity());
28	        }
29	    }
30	}
