21	    private static final int DAILY_LIMIT = 100;
22	
23	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
24	            throws TooManyOwnersTodayException {
25	        LocalDate supplied = request.getRegistrationDate();
26	        LocalDate businessDay = BusinessDays.rollForward(supplied != null ? supplied : LocalDate.now());
27	        int count = 0;
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (businessDay.equals(existing.getRegistrationDate())) {
30	                count++;
31	            }
32	        }
