3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HashSet;
7	import java.util.Set;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	
13	/**
14	 * Assigns the owner's {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} where:
15	 * <ul>
16	 * <li>REGION is the version-2 region code — the postcode-derived region carrying the fixed 'V2'
17	 * version tag, e.g. {@code V2NSW} (see {@link OwnerRegion#identityRegion(Owner)}),</li>
18	 * <li>FY is the two-digit fiscal year (1 July basis) of the {@code registrationDate} (see
19	 * {@link FiscalYear}),</li>
20	 * <li>HASH8 is the first eight upper-case hex characters of SHA-256 over the concatenation of the
21	 * owner's normalized (E.164) telephone and last name — the same value used by the region-and-hash
22	 * identity, and</li>
23	 * <li>CHK is a single Luhn check digit computed over the decimal digits of
24	 * {@code <REGION><FY><HASH8>}.</li>
25	 * </ul>
26	 * For example {@code V2NSW271A2B3C4D6}. There is no sequence number, so the id is stable for a given
27	 * region, fiscal year, telephone and last name and does not depend on how many owners already exist.
28	 * Runs after the customer's registration date has been assigned.
29	 *
30	 * <p>Should the computed id collide with an already-assigned {@code memberId} (a hash collision, or
31	 * the same region, fiscal year and hash on distinct owners), it is de-duplicated by appending
32	 * {@code -<n>} with the smallest {@code n} of 2 or more that makes it unique among existing owners.
33	 */
34	public class AssignMemberId {
35	
36	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
37	        String region = OwnerRegion.identityRegion(owner);
38	        String fy = String.format("%02d", FiscalYear.endingYear(owner.getRegistrationDate()) % 100);
39	        String body = region + fy + hash8(owner);
40	        String memberId = body + luhn(body);
41	        owner.setMemberId(deduplicate(memberId, ownerRepository));
42	    }
43	
44	    /**
45	     * Returns {@code memberId} unchanged when no existing owner already uses it, otherwise
46	     * {@code memberId-<n>} with the smallest {@code n >= 2} that is not already in use.
47	     */
48	    private static String deduplicate(String memberId, OwnerRepository ownerRepository) {
49	        Set<String> existing = new HashSet<>();
50	        for (Owner other : ownerRepository.findAll()) {
51	            if (other.getMemberId() != null) {
52	                existing.add(other.getMemberId());
53	            }
54	        }
55	        if (!existing.contains(memberId)) {
56	            return memberId;
57	        }
58	        for (int n = 2; ; n++) {
59	            String candidate = memberId + "-" + n;
60	            if (!existing.contains(candidate)) {
61	                return candidate;
62	            }
63	        }
64	    }
65	
66	    /** First eight upper-case hex characters of SHA-256(normalizedTelephone + lastName). */
67	    private static String hash8(Owner owner) {
68	        // The stored telephone is already E.164 (see NormalizeOwnerTelephone); re-normalizing is
69	        // idempotent and falls back to the stored value if it somehow cannot be parsed.
70	        String normalizedTelephone = E164Telephone.toE164OrNull(owner.getTelephone());
71	        if (normalizedTelephone == null) {
72	            normalizedTelephone = owner.getTelephone() == null ? "" : owner.getTelephone();
73	        }
74	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
75	        try {
76	            byte[] digest = MessageDigest.getInstance("SHA-256")
77	                    .digest((normalizedTelephone + lastName).getBytes(StandardCharsets.UTF_8));
78	            StringBuilder sb = new StringBuilder(8);
79	            for (int i = 0; i < 4; i++) {
80	                sb.append(String.format("%02X", digest[i]));
81	            }
82	            return sb.toString();
83	        }
84	        catch (NoSuchAlgorithmException e) {
85	            throw new IllegalStateException("SHA-256 unavailable", e);
86	        }
87	    }
88	
89	    /** Luhn check digit (0-9) over the decimal digits contained in {@code value}. */
90	    private static int luhn(String value) {
91	        int sum = 0;
92	        boolean dbl = true;
93	        for (int i = value.length() - 1; i >= 0; i--) {
94	            char c = value.charAt(i);
95	            if (c < '0' || c > '9') {
96	                continue;
97	            }
98	            int d = c - '0';
99	            if (dbl) {
100	                d *= 2;
101	                if (d > 9) {
102	                    d -= 9;
103	                }
104	            }
105	            sum += d;
106	            dbl = !dbl;
107	        }
108	        return (10 - (sum % 10)) % 10;
109	    }
110	}
