8	/**
9	 * Flags a soft (non-hard) duplicate on the owner being created. A hard duplicate — the same
10	 * {@link OwnerIdentityKey} as an existing owner — is already rejected with 409 by
11	 * {@link EnsureUniqueIdentity} before this step runs, unless the request opted into a shared household
12	 * with {@code sharesHousehold}. This step then looks for an existing non-deleted owner whose
13	 * {@code soundex(lastName)} and postcode match this owner's but whose identity key <em>differs</em>:
14	 * such an owner is still created, but is marked {@code possibleDuplicate = true} with
15	 * {@code possibleDuplicateOf} set to the matching owner's id. When no such owner exists,
16	 * {@code possibleDuplicate} is {@code false}.
17	 *
18	 * <p>A declared household member (created with {@code sharesHousehold} true) is never a suspected
19	 * duplicate, so it is never flagged.
20	 *
21	 * <p>Runs after {@link BuildOwner} (so the owner already carries the normalized E.164 telephone and
22	 * the postcode) and before {@link SaveOwner}.
23	 */
24	public class AssignPossibleDuplicate {
25	
26	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
27	        owner.setPossibleDuplicate(false);
28	        owner.setPossibleDuplicateOf(null);
29	
30	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            return; // a declared household member is not a suspected duplicate
32	        }
33	
34	        String postcode = normalizePostcode(owner.getPostcode());
35	        if (postcode == null) {
36	            return; // no postcode means it cannot share a postcode with anyone
37	        }
38	        String soundex = Soundex.of(owner.getLastName());
39	        String identityKey = OwnerIdentityKey.of(owner);
40	
41	        for (Owner existing : ownerRepository.findAll()) {
42	            if (existing.isDeleted()) {
43	                continue; // a soft-deleted owner is ignored by the identity check
44	            }
45	            if (!postcode.equals(normalizePostcode(existing.getPostcode()))) {
46	                continue;
47	            }
48	            if (!soundex.equals(Soundex.of(existing.getLastName()))) {
49	                continue;
50	            }
51	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
52	                continue; // same identity key is a hard duplicate concern, not a soft match
53	            }
54	            owner.setPossibleDuplicate(true);
55	            owner.setPossibleDuplicateOf(existing.getId());
56	            return;
57	        }
58	    }
59	
60	    private static String normalizePostcode(String postcode) {
61	        if (postcode == null) {
62	            return null;
63	        }
64	        String trimmed = postcode.trim();
65	        return trimmed.isEmpty() ? null : trimmed;
66	    }
67	}
