6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.function.owner.AgeBand;
9	import org.springframework.samples.petclinic.rest.function.owner.OwnerRegion;
10	import org.springframework.samples.petclinic.rest.function.owner.FiscalYear;
11	import org.springframework.samples.petclinic.rest.function.owner.LocalityTimezone;
12	import org.springframework.samples.petclinic.rest.function.owner.OwnerIdentityKey;
13	import org.springframework.samples.petclinic.rest.function.owner.OwnerRisk;
14	import org.springframework.samples.petclinic.rest.function.owner.OwnerSegment;
15	import org.springframework.samples.petclinic.rest.function.owner.TelephoneDisplay;
16	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
17	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
18	import org.springframework.samples.petclinic.rest.dto.OwnerIdentityDto;
19	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
20	
21	import java.util.Collection;
22	import java.util.List;
23	
24	/**
25	 * Maps Owner & OwnerDto using Mapstruct
26	 */
27	@Mapper(uses = PetMapper.class, imports = {OwnerDto.class, OwnerIdentityKey.class, OwnerRegion.class, LocalityTimezone.class, AgeBand.class, FiscalYear.class, TelephoneDisplay.class, OwnerSegment.class, OwnerRisk.class})
28	public interface OwnerMapper {
29	
30	    @Mapping(target = "selfLink",
31	            expression = "java(\"/api/owners/\" + owner.getId())")
32	    @Mapping(target = "salutation",
33	            expression = "java(owner.getTitle() != null && !owner.getTitle().isBlank() ? owner.getTitle() + \" \" + owner.getLastName() : owner.getLastName())")
34	    @Mapping(target = "displayName",
35	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
36	    @Mapping(target = "initials",
37	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
38	    @Mapping(target = "locality",
39	            expression = "java(OwnerRegion.of(owner))")
40	    @Mapping(target = "timezone",
41	            expression = "java(LocalityTimezone.of(owner))")
42	    @Mapping(target = "contactPreference",
43	            expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE)")
44	    @Mapping(target = "apiVersion",
45	            expression = "java(2)")
46	    @Mapping(target = "identity",
47	            expression = "java(toIdentity(owner))")
48	    @Mapping(target = "ageBand",
49	            expression = "java(AgeBand.of(owner))")
50	    @Mapping(target = "ownerSegment",
51	            expression = "java(OwnerSegment.of(owner))")
52	    @Mapping(target = "fiscalYear",
53	            expression = "java(FiscalYear.label(owner.getRegistrationDate()))")
54	    @Mapping(target = "telephoneDisplay",
55	            expression = "java(TelephoneDisplay.of(owner))")
56	    @Mapping(target = "riskFlag",
57	            expression = "java(OwnerRisk.of(owner))")
58	    OwnerDto toOwnerDto(Owner owner);
59	
60	    Owner toOwner(OwnerDto ownerDto);
61	
62	    /**
63	     * The owner's version-2 identity object grouping its derived identifiers. The identityKey is
64	     * recomputed at read time; the memberId and householdId are read from the stored owner (both
65	     * assigned at creation with the version-2 region code, see {@link OwnerIdentityKey}).
66	     */
67	    default OwnerIdentityDto toIdentity(Owner owner) {
68	        OwnerIdentityDto identity = new OwnerIdentityDto();
69	        identity.setMemberId(owner.getMemberId());
70	        identity.setIdentityKey(OwnerIdentityKey.of(owner));
71	        identity.setHouseholdId(owner.getHouseholdId());
72	        return identity;
73	    }
74	
75	    @Mapping(target = "id", ignore = true)
76	    @Mapping(target = "pets", ignore = true)
77	    Owner toOwner(OwnerFieldsDto ownerDto);
78	
79	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
80	
81	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
82	
83	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
84	        OwnerPageDto ownerPageDto = new OwnerPageDto();
85	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
86	        ownerPageDto.setPage(ownerPage.getNumber());
87	        ownerPageDto.setSize(ownerPage.getSize());
88	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
89	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
90	        return ownerPageDto;
91	    }
92	}
